using System;using System.Linq;using System.IO;using System.Reflection;using UnityEngine;
public static class SnapshotSharkReviewV241{
 public static object Run(){var observer=UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None).First(x=>x.GetType().Name=="SharkAnimationObserverV241");var type=observer.GetType();var flags=BindingFlags.Instance|BindingFlags.NonPublic;object Read(string n)=>type.GetField(n,flags).GetValue(observer);var battle=(Story1WreckBattle)Read("battle");var sequence=(Story1SharkCollisionSequence)Read("sequence");var folder=(string)type.GetField("folder").GetValue(observer);var data=new{frame=Read("frame"),fps=type.GetField("fps").GetValue(observer),rows=Read("rows"),frameMap=Read("frameMap"),events=battle.RedesignEvents,health=sequence.sahur.GetComponent<Mavis.PlayerHealth>().currentHealth};File.WriteAllText(folder+"/partial.json",Newtonsoft.Json.JsonConvert.SerializeObject(data,Newtonsoft.Json.Formatting.Indented));return new{battle.RedesignStage,battle.RedesignClock,battle.RedesignDeckClearance,hero=sequence.sahur.transform.position.ToString(),folder};}
}